firmware:
#include <Stepper.h>

const int STEPS_PER_REV = 200;
const int A_PLUS = 13;
const int A_MINUS = 12;
const int B_PLUS = 14;
const int B_MINUS = 27;
Stepper motor(STEPS_PER_REV, A_PLUS, A_MINUS, B_PLUS, B_MINUS);

void setup() {
  Serial.begin(115200);
  motor.setSpeed(60);
  motor.step(STEPS_PER_REV);
  delay(200);
  motor.step(-STEPS_PER_REV);
  Serial.println("DONE");
}

void loop() {
  delay(1000);
}
